def tint(c, k=0.015):
    return tuple(np.clip(np.array(c) * (1 + rng.normal(0, k)), 0, 1))


def B(x0, x1, y0, y1, z0, z1, c):
    return box(x1 - x0, y1 - y0, z1 - z0, c).T((x0 + x1) / 2, y0, (z0 + z1) / 2)


def sphere(r, c, seg=10, rings=6):
    prof = [(r * math.sin(t), -r * math.cos(t)) for t in np.linspace(0, math.pi, rings + 1)]
    return lathe(prof, c, seg)


def inside(x, z, P):
    ins = False
    for i in range(len(P)):
        (xi, zi), (xj, zj) = P[i], P[i - 1]
        if (zi > z) != (zj > z) and x < (xj - xi) * (z - zi) / (zj - zi) + xi:
            ins = not ins
    return ins


def ccw(P):
    P = [tuple(p) for p in P]
    if len(P) > 1 and math.dist(P[0], P[-1]) < 1e-6:
        P = P[:-1]
    return P if ring_area(P) > 0 else P[::-1]


def bbox(P):
    xs = [p[0] for p in P]; zs = [p[1] for p in P]
    return min(xs), max(xs), min(zs), max(zs)


def clip(P, axis, val, keep_less):
    out = []
    n = len(P)
    for i in range(n):
        a, b = P[i], P[(i + 1) % n]
        ia = (a[axis] <= val) if keep_less else (a[axis] >= val)
        ib = (b[axis] <= val) if keep_less else (b[axis] >= val)
        if ia:
            out.append(a)
        if ia != ib:
            t = (val - a[axis]) / (b[axis] - a[axis])
            out.append((a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t))
    return out


class Face:
    """A wall plane: a = start point (x, z), t = direction along the wall, n = outward normal; local (u, y, w)."""

    def __init__(self, a, t, n):
        self.a, self.t, self.n = np.asarray(a, float), np.asarray(t, float), np.asarray(n, float)

    def P(self, u, y, w):
        p = self.a + self.t * u + self.n * w
        return (p[0], y, p[1])

    def poly(self, pts, c, w=0.05):
        V = [self.P(u, y, w) for u, y in pts]
        F = [(0, i, i + 1) for i in range(1, len(V) - 1)]
        m = Mesh(V, F, c)
        a, b, cc = np.array(V[0]), np.array(V[1]), np.array(V[2])
        nn = np.cross(b - a, cc - a)
        if np.dot([nn[0], nn[2]], self.n) < 0:
            m.f = m.f[:, ::-1]
        return m

    def slab(self, u0, u1, y0, y1, w0, w1, c):
        P = [self.P(u, y, w) for w in (w0, w1) for y in (y0, y1) for u in (u0, u1)]
        quads = [(4, 5, 7, 6), (1, 0, 2, 3), (0, 4, 6, 2), (5, 1, 3, 7), (6, 7, 3, 2), (0, 1, 5, 4)]
        V, F = [], []
        for q in quads:
            o = len(V); V += [P[k] for k in q]; F += [(o, o + 1, o + 2), (o, o + 2, o + 3)]
        m = Mesh(V, F, c)
        ctr = np.mean(np.array(P), 0)
        for k in range(0, len(F), 2):
            a, b, cc = (np.array(V[i]) for i in F[k])
            if np.dot(np.cross(b - a, cc - a), (a + b + cc) / 3 - ctr) < 0:
                m.f[k] = m.f[k][::-1]; m.f[k + 1] = m.f[k + 1][::-1]
        return m


def arch_pts(u, y0, ys, half, seg=5):
    pts = [(u - half, y0), (u + half, y0)]
    pts += [(u + half * math.cos(a), ys + half * math.sin(a)) for a in np.linspace(0, math.pi, seg + 1)]
    return pts


def rect_pts(u, y, w, h):
    return [(u - w / 2, y - h / 2), (u + w / 2, y - h / 2), (u + w / 2, y + h / 2), (u - w / 2, y + h / 2)]


def face_of(x0, z0, x1, z1, n):
    a, b = np.array([x0, z0], float), np.array([x1, z1], float)
    L = float(np.linalg.norm(b - a))
    return Face(a, (b - a) / L, n), L


def hip_roof(x0, x1, z0, z1, E, R, c, inset=0.0):
    x0, x1, z0, z1 = x0 + inset, x1 - inset, z0 + inset, z1 - inset
    L, W = x1 - x0, z1 - z0
    R = min(R, 0.5 * min(L, W) * 0.75)
    if L >= W:
        a, b = (x0 + W / 2, (z0 + z1) / 2), (x1 - W / 2, (z0 + z1) / 2)
    else:
        a, b = ((x0 + x1) / 2, z0 + L / 2), ((x0 + x1) / 2, z1 - L / 2)
    Y = E + R
    c00, c10, c11, c01 = (x0, E, z0), (x1, E, z0), (x1, E, z1), (x0, E, z1)
    A, Bp = (a[0], Y, a[1]), (b[0], Y, b[1])
    if L >= W:
        faces = [(c00, c10, Bp, A), (c11, c01, A, Bp), (c01, c00, A), (c10, c11, Bp)]
    else:
        faces = [(c10, c11, Bp, A), (c01, c00, A, Bp), (c00, c10, A), (c11, c01, Bp)]
    V, F = [], []
    for fc in faces:
        o = len(V); V += list(fc)
        F += [(o, o + 2, o + 1)] + ([(o, o + 3, o + 2)] if len(fc) == 4 else [])
    m = Mesh(V, F, c)
    a_, b_, c_ = m.v[m.f[:, 0]], m.v[m.f[:, 1]], m.v[m.f[:, 2]]
    flip = np.cross(b_ - a_, c_ - a_)[:, 1] < 0
    m.f[flip] = m.f[flip][:, ::-1]
    return m


def urn(x, y, z, s=1.0, c=STONE):
    return lathe([(0.0, 0.0), (0.28 * s, 0.0), (0.18 * s, 0.25 * s), (0.34 * s, 0.6 * s), (0.2 * s, 0.95 * s),
                  (0.1 * s, 1.05 * s), (0.12 * s, 1.25 * s), (0.0, 1.3 * s)], c, 8).T(x, y, z)


def statue(x, y, z, h=2.4, c=MARBLE, seg=8):
    k = h / 4.2
    body = lathe([(0.0, 0.0), (0.62, 0.0), (0.62, 0.25), (0.55, 0.3), (0.62, 1.6), (0.55, 2.6), (0.62, 3.05),
                  (0.42, 3.35), (0.18, 3.45), (0.0, 3.46)], c, seg)
    head = sphere(0.3, c, seg, 5).T(0, 3.72, 0)
    return merge([body, head]).S(k).T(x, y, z)


def balustrade(f, u0, u1, y, h=1.1, urns=0.0, w=0.0):
    """A stone balustrade along a face, on top of the wall (y), set w metres in from the face."""
    out = [f.slab(u0, u1, y, y + 0.25, -w - 0.35, -w + 0.05, STONE),
           f.slab(u0, u1, y + 0.25, y + h - 0.2, -w - 0.25, -w - 0.05, tint(STONE, 0.01)),
           f.slab(u0, u1, y + h - 0.2, y + h, -w - 0.35, -w + 0.05, STONE)]
    if urns:
        n = max(1, int(round((u1 - u0) / urns)))
        for k in range(n + 1):
            p = f.P(u0 + (u1 - u0) * k / n, y + h, -w - 0.15)
            out.append(B(p[0] - 0.3, p[0] + 0.3, y + h, y + h + 0.35, p[2] - 0.3, p[2] + 0.3, STONE))
            out.append(urn(p[0], y + h + 0.35, p[2], 0.9))
    return out


# ── Windows and walls of the palace ───────────────────────────────────────────
def bays(L, step, margin=1.6):
    n = max(1, int(round((L - 2 * margin) / step)))
    s = (L - 2 * margin) / n
    return [margin + s * (k + 0.5) for k in range(n)], s


def win_arch(f, u, y0, w, h, c=GLASS):
    """An arched window with its stone frame."""
    return [f.poly(arch_pts(u, y0 - 0.25, y0 + h - w / 2, w / 2 + 0.3), STONE, 0.03),
            f.poly(arch_pts(u, y0, y0 + h - w / 2, w / 2), c, 0.06)]


def win_rect(f, u, y0, w, h, balcony=False, pediment=False):
    out = [f.poly(rect_pts(u, y0 + h / 2, w + 0.55, h + 0.5), STONE, 0.03),
           f.poly(rect_pts(u, y0 + h / 2, w, h), GLASS, 0.06)]
    if pediment:
        out.append(f.slab(u - w / 2 - 0.45, u + w / 2 + 0.45, y0 + h + 0.25, y0 + h + 0.6, -0.02, 0.35, STONE))
    if balcony:
        out.append(f.slab(u - w / 2 - 0.4, u + w / 2 + 0.4, y0 - 0.25, y0, 0.0, 0.75, STONE))
        out.append(f.slab(u - w / 2 - 0.3, u + w / 2 + 0.3, y0 + 0.9, y0 + 0.97, 0.6, 0.68, IRON))
        out.append(f.slab(u - w / 2 - 0.3, u + w / 2 + 0.3, y0, y0 + 0.97, 0.63, 0.65, (0.16, 0.16, 0.17)))
    return out


def dress(f, L, E, floors, step=4.6, skip=(), string=None, pil=True, corners=True):
    """Stone dressing of a brick wall: plinth, string course, cornice, pilaster strips between the bays,
    quoins, and the windows. floors = [(kind, y0, w, h)], kind in 'arch', 'rect', 'bal', 'arcade'."""
    out = [f.slab(-0.2, L + 0.2, FOUND, 0.9, -0.05, 0.18, STONE_D),
           f.slab(-0.35, L + 0.35, E - 0.75, E, -0.05, 0.5, STONE)]
    if string:
        out.append(f.slab(-0.25, L + 0.25, string - 0.35, string, -0.05, 0.3, STONE))
    us, s = bays(L, step)
    if corners:
        out += [f.slab(-0.05, 1.0, 0.9, E - 0.75, -0.05, 0.12, STONE), f.slab(L - 1.0, L + 0.05, 0.9, E - 0.75, -0.05, 0.12, STONE)]
    for i, u in enumerate(us):
        if any(a <= u <= b for a, b in skip):
            continue
        if pil and i > 0:
            out.append(f.slab(u - s / 2 - 0.35, u - s / 2 + 0.35, 0.9, E - 0.75, -0.05, 0.1, STONE))
        for kind, y0, w, h in floors:
            if kind == "arch":
                out += win_arch(f, u, y0, w, h)
            elif kind == "arcade":
                out += win_arch(f, u, y0, min(w, s * 0.7), h, DARK)
            elif kind == "bal":
                out += win_rect(f, u, y0, w, h, balcony=True, pediment=True)
            else:
                out += win_rect(f, u, y0, w, h)
    return out


RANGE_FLOORS = [("arch", 1.6, 1.4, 3.6), ("bal", 9.0, 1.4, 3.4), ("rect", 13.6, 1.1, 1.2)]
WING_IN = [("arcade", 0.0, 3.2, 4.9), ("bal", 7.2, 1.3, 3.0)]
WING_OUT = [("rect", 1.6, 1.3, 2.6), ("bal", 7.2, 1.3, 3.0)]
E_RANGE, E_WING = 17.0, 12.8


def block(x0, x1, z0, z1, E, faces, floors, roof=True, R=4.5, string=8.3, step=4.6):
    """A rectangular brick block; faces = dict side -> dressed?, side in '+x', '-x', '+z', '-z'."""
    out = [B(x0, x1, FOUND, E, z0, z1, tint(BRICK, 0.02))]
    sides = {"+x": (x1, z1, x1, z0, (1, 0)), "-x": (x0, z0, x0, z1, (-1, 0)),
             "+z": (x0, z1, x1, z1, (0, 1)), "-z": (x1, z0, x0, z0, (0, -1))}
    for k, fl in faces.items():
        if fl is None:
            continue
        xa, za, xb, zb, n = sides[k]
        f, L = face_of(xa, za, xb, zb, n)
        out += dress(f, L, E, fl, step=step, string=string)
    if roof:
        out.append(hip_roof(x0, x1, z0, z1, E, R, tint(SLATE, 0.02), inset=0.6))
        out.append(B(x0 + 0.5, x1 - 0.5, E - 0.1, E + 0.05, z0 + 0.5, z1 - 0.5, LEAD_D))
    return out


def chimneys(pts, y, h=2.2):
    out = []
    for x, z in pts:
        out += [B(x - 0.6, x + 0.6, y - 2.0, y + h, z - 0.9, z + 0.9, tint(STONE, 0.01)),
                B(x - 0.75, x + 0.75, y + h, y + h + 0.3, z - 1.05, z + 1.05, STONE)]
    return out


# ── The palace ───────────────────────────────────────────────────────────────
ZF = 0.8          # the plaza front of the west range
XT = 41.3         # inner faces of the towers and wings (±)


def palace():
    out = []
    # west range on the plaza, between the towers
    out += block(-XT, XT, -19.4, ZF, E_RANGE, {}, RANGE_FLOORS, roof=False)
    for xa, xb in ((55.2, 31.3), (-33.5, -55.4)):                      # its back, over the Rey and Reina gardens
        f, L = face_of(xa, -19.4, xb, -19.4, (0, -1))
        out += dress(f, L, E_RANGE, RANGE_FLOORS, string=8.3)
    out.append(hip_roof(-55.4, 55.2, -19.4, ZF, E_RANGE, 4.5, tint(SLATE, 0.02), inset=0.9))
    # north and south ends of the range behind the towers (x beyond the towers, z −19.4…−13.3)
    for x0, x1 in ((-55.4, -XT), (XT, 55.2)):
        out.append(B(x0, x1, FOUND, E_RANGE, -19.4, -13.3, tint(BRICK, 0.02)))
    f, L = face_of(55.2, -13.3, 55.2, -19.4, (1, 0))
    out += dress(f, L, E_RANGE, RANGE_FLOORS, string=8.3)
    f, L = face_of(-55.4, -19.4, -55.4, -13.3, (-1, 0))
    out += dress(f, L, E_RANGE, RANGE_FLOORS, string=8.3)
    # the plaza front of the range (between the towers), with the central body left out
    for xa, xb in ((-XT, -14.6), (14.6, XT)):
        f, L = face_of(xa, ZF, xb, ZF, (0, 1))
        out += dress(f, L, E_RANGE, RANGE_FLOORS, string=8.3)
        out += balustrade(f, -0.2, L + 0.2, E_RANGE, 1.1, urns=6.0)
    out += central_body()
    # the block round the courtyard (east), and the courtyard
    blk = [(-33.5, -12.6, -64.9, -19.4, "N"), (13.7, 31.3, -64.9, -19.4, "S"), (-12.6, 13.7, -64.9, -45.9, "E")]
    for x0, x1, z0, z1, k in blk:
        faces = {"-z": RANGE_FLOORS}
        if k == "N":
            faces.update({"-x": RANGE_FLOORS, "+x": RANGE_FLOORS})
        elif k == "S":
            faces.update({"+x": RANGE_FLOORS, "-x": RANGE_FLOORS})
        else:
            faces.update({"+z": RANGE_FLOORS})
        out += block(x0, x1, z0, z1, E_RANGE, faces, RANGE_FLOORS, roof=False)
    out.append(hip_roof(-33.5, -12.6, -64.9, -19.4, E_RANGE, 4.5, tint(SLATE, 0.02), inset=0.6))
    out.append(hip_roof(13.7, 31.3, -64.9, -19.4, E_RANGE, 4.5, tint(SLATE, 0.02), inset=0.6))
    out.append(hip_roof(-14.0, 15.0, -64.9, -45.9, E_RANGE, 4.5, tint(SLATE, 0.02), inset=0.6))
    f, L = face_of(13.7, -19.4, -12.6, -19.4, (0, -1))
    out += dress(f, L, E_RANGE, RANGE_FLOORS, string=8.3)          # the courtyard side of the west range
    out.append(cap(DATA["courtyard"], 0.04, (0.74, 0.70, 0.62)))
    # balustrade on the garden front (on the Parterre)
    f, L = face_of(31.3, -64.9, -33.5, -64.9, (0, -1))
    out += balustrade(f, -0.2, L + 0.2, E_RANGE, 1.1, urns=6.5)
    # the two corner towers
    for x0, x1 in ((-55.4, -XT), (XT, 56.3)):
        out += tower(x0, x1, -13.3, ZF)
    # Sabatini's wings
    out += wing(XT, 60.9, 1)
    out += wing(-59.6, -XT, -1)
    # chimneys along the ridges
    out += chimneys([(-30.0, -9.3), (-12.0, -9.3), (12.0, -9.3), (30.0, -9.3), (-23.0, -35.0), (-23.0, -52.0),
                     (22.5, -35.0), (22.5, -52.0), (0.0, -55.4)], E_RANGE + 3.2)
    return out


def central_body():
    """Bonavía's central body: five arches, balconies, the attic storey with the arms of Ferdinand VI, the curved
    pediment and the three kings (Philip II, Philip V, Ferdinand VI) by Pedro Martinengo."""
    out = []
    x0, x1, z1 = -14.6, 14.6, ZF + 1.2
    out.append(B(x0, x1, FOUND, 24.5, -12.0, z1, tint(BRICK, 0.02)))
    f, L = face_of(x0, z1, x1, z1, (0, 1))
    out += [f.slab(-0.2, L + 0.2, FOUND, 0.9, -0.05, 0.2, STONE_D), f.slab(-0.4, L + 0.4, 7.9, 8.6, -0.05, 0.45, STONE),
            f.slab(-0.4, L + 0.4, 16.2, 17.0, -0.05, 0.5, STONE), f.slab(-0.5, L + 0.5, 23.7, 24.5, -0.05, 0.6, STONE)]
    us = [L / 2 + k * 5.4 for k in (-2, -1, 0, 1, 2)]
    for u in us:                                                        # the portico
        out.append(f.poly(arch_pts(u, 0.0, 5.6, 1.75), DARK, 0.06))
    for u in [L / 2 + k * 5.4 for k in (-2.5, -1.5, -0.5, 0.5, 1.5, 2.5)]:
        out.append(f.slab(u - 0.85, u + 0.85, 0.9, 7.9, -0.05, 0.45, STONE))   # piers with pilasters
        out.append(f.slab(u - 0.5, u + 0.5, 8.6, 23.7, -0.05, 0.3, STONE))
    out.append(f.slab(us[0] - 2.4, us[-1] + 2.4, 8.6, 8.8, 0.0, 1.4, STONE))   # the balcony over the portico
    out += balustrade(f, us[0] - 2.4, us[-1] + 2.4, 8.8, 1.0, w=-1.4)
    for u in us:
        out += win_rect(f, u, 9.4, 1.5, 3.6, pediment=True)
        out += win_rect(f, u, 18.2, 1.3, 2.6)
    # attic: the arms panel and the curved pediment
    out.append(f.slab(L / 2 - 4.5, L / 2 + 4.5, 24.5, 27.5, -0.4, 0.4, tint(BRICK, 0.01)))
    prof = [(L / 2 - 6.5 + 13.0 * k / 8, 27.5 - 1.6 * (1 - math.sin(math.pi * k / 8))) for k in range(9)]
    poly = [(L / 2 - 7.2, 24.5)] + prof + [(L / 2 + 7.2, 24.5)]
    out.append(f.poly(poly, tint(BRICK, 0.01), 0.42))
    for a, b in zip(prof[:-1], prof[1:]):
        out.append(face_slab_seg(f, a, b, 0.5))
    out.append(f.poly(rect_pts(L / 2, 25.6, 3.0, 2.2), STONE, 0.47))     # the arms of Ferdinand VI
    out += balustrade(f, -0.2, L / 2 - 6.6, 24.5, 1.0, urns=4.5)
    out += balustrade(f, L / 2 + 6.6, L + 0.2, 24.5, 1.0, urns=4.5)
    for u, y in ((L / 2, 27.5), (L / 2 - 6.6, 25.6), (L / 2 + 6.6, 25.6)):
        p = f.P(u, y, -0.1)
        out.append(B(p[0] - 0.55, p[0] + 0.55, y, y + 0.6, p[2] - 0.5, p[2] + 0.5, STONE))
        out.append(statue(p[0], y + 0.6, p[2], 2.3))
    # sides of the projecting body and its roof
    for xa, n in ((x0, (-1, 0)), (x1, (1, 0))):
        g, L2 = face_of(xa, -12.0, xa, z1, n)
        out.append(g.slab(-0.2, L2 + 0.2, 23.7, 24.5, -0.05, 0.5, STONE))
    out.append(hip_roof(x0, x1, -12.0, z1 - 1.5, 24.5, 2.5, SLATE, inset=1.2))
    return out


def face_slab_seg(f, a, b, w):
    """A stone moulding following a sloping segment (u, y) on the face."""
    (u0, y0), (u1, y1) = a, b
    P0, P1 = np.array(f.P(u0, y0, 0.0)), np.array(f.P(u1, y1, 0.0))
    d = P1 - P0
    nrm = np.array([f.n[0], 0, f.n[1]])
    up = np.cross(nrm, d); up = up / np.linalg.norm(up) * 0.3
    if up[1] < 0:
        up = -up
    out = nrm * (w + 0.15)
    V = [P0, P1, P1 + up, P0 + up, P0 + out, P1 + out, P1 + up + out, P0 + up + out]
    F = [(0, 1, 2), (0, 2, 3), (4, 6, 5), (4, 7, 6), (3, 2, 6), (3, 6, 7), (0, 5, 1), (0, 4, 5), (0, 3, 7), (0, 7, 4), (1, 5, 6), (1, 6, 2)]
    return Mesh(V, F, STONE)


def tower(x0, x1, z0, z1):
    """A corner tower: brick and stone body to 24 m, balustrade with urns, drum with oculi, lead dome,
    lantern, ball and cross."""
    out = [B(x0, x1, FOUND, 24.0, z0, z1, tint(BRICK, 0.02))]
    cx, cz = (x0 + x1) / 2, (z0 + z1) / 2
    floors = [("arch", 1.6, 1.4, 3.6), ("bal", 9.0, 1.4, 3.4), ("bal", 15.6, 1.2, 2.6), ("arch", 20.4, 1.0, 2.2)]
    for xa, za, xb, zb, n in ((x0, z1, x1, z1, (0, 1)), (x1, z1, x1, z0, (1, 0)), (x0, z0, x0, z1, (-1, 0)), (x1, z0, x0, z0, (0, -1))):
        f, L = face_of(xa, za, xb, zb, n)
        out += dress(f, L, 24.0, floors, step=4.6, string=8.3)
        out.append(f.slab(-0.3, L + 0.3, 16.6, 17.0, -0.05, 0.35, STONE))
        out += balustrade(f, -0.3, L + 0.3, 24.0, 1.0, w=-0.2)
    for sx in (x0 + 0.3, x1 - 0.3):
        for sz in (z0 + 0.3, z1 - 0.3):
            out.append(urn(sx, 25.0, sz, 1.1))
    r = 5.3
    out += [cyl(r, r, 5.0, tint(BRICK, 0.01), 24, caps=False).T(cx, 24.0, cz),
            cyl(r + 0.3, r + 0.3, 0.5, STONE, 24).T(cx, 24.0, cz),
            cyl(r + 0.35, r + 0.35, 0.6, STONE, 24).T(cx, 28.6, cz)]
    for k in range(8):                                                      # pilasters and oculi round the drum
        a = 2 * math.pi * k / 8
        n = np.array([math.cos(a), math.sin(a)]); t = np.array([-n[1], n[0]])
        f = Face(np.array([cx, cz]) + n * r, t, n)
        out.append(f.slab(-0.35, 0.35, 24.5, 28.6, -0.1, 0.2, STONE))
        if k % 2:
            ring = [(0.75 * math.cos(q), 26.6 + 0.75 * math.sin(q)) for q in np.linspace(0, 2 * math.pi, 9)[:-1]]
            out.append(f.poly(ring, GLASS, 0.06))
    out.append(lathe([(r + 0.2, 0.0), (r, 0.8), (4.6, 2.2), (3.4, 3.4), (1.9, 4.1), (1.2, 4.3), (0.0, 4.35)],
                     tint(LEAD, 0.02), 24).T(cx, 29.2, cz))
    y = 33.4
    out += [cyl(1.25, 1.25, 2.3, SLATE, 10).T(cx, y, cz), cyl(1.5, 1.5, 0.3, LEAD, 10).T(cx, y + 2.3, cz)]
    for k in range(4):
        a = 2 * math.pi * k / 4 + math.pi / 4
        n = np.array([math.cos(a), math.sin(a)]); t = np.array([-n[1], n[0]])
        f = Face(np.array([cx, cz]) + n * 1.25, t, n)
        out.append(f.poly(arch_pts(0.0, y + 0.4, y + 1.5, 0.4), GLASS, 0.04))
    out += [lathe([(1.4, 0.0), (0.9, 0.7), (0.3, 1.4), (0.18, 2.4), (0.0, 2.5)], SLATE, 10).T(cx, y + 2.6, cz),
            sphere(0.3, GOLD, 8, 5).T(cx, y + 5.3, cz),
            B(cx - 0.06, cx + 0.06, y + 5.5, y + 7.1, cz - 0.06, cz + 0.06, IRON),
            B(cx - 0.45, cx + 0.45, y + 6.4, y + 6.52, cz - 0.05, cz + 0.05, IRON)]
    return out


def wing(x0, x1, side):
    """A wing of the Plaza de Armas (Sabatini): two storeys, the arcade on the plaza, a flat roof behind a
    balustrade with urns, three arches at the west end. side = +1 (south wing) or −1 (north wing)."""
    out = []
    z0, z1 = ZF, 89.2
    zo = 12.2                                                  # the outer face starts here (the tower before it)
    xi, xo = (x0, x1) if side > 0 else (x1, x0)                # inner (plaza) and outer x
    out.append(B(min(xi, xo), max(xi, xo), FOUND, E_WING, zo, z1, tint(BRICK, 0.02)))
    xm = xi + side * 15.0                                      # the part between the tower and zo
    out.append(B(min(xi, xm), max(xi, xm), FOUND, E_WING, z0, zo, tint(BRICK, 0.02)))
    # plaza side, arcade
    f, L = face_of(xi, z1, xi, z0, (-side, 0)) if side > 0 else face_of(xi, z0, xi, z1, (-side, 0))
    out += dress(f, L, E_WING, WING_IN, step=4.5, string=6.6)
    out += balustrade(f, -0.2, L + 0.2, E_WING, 1.1, urns=6.0)
    # outer side
    f, L = face_of(xo, zo, xo, z1, (side, 0)) if side > 0 else face_of(xo, z1, xo, zo, (side, 0))
    out += dress(f, L, E_WING, WING_OUT, step=4.5, string=6.6)
    out += balustrade(f, -0.2, L + 0.2, E_WING, 1.1, urns=6.0)
    # the west end, three great arches
    f, L = face_of(min(xi, xo), z1, max(xi, xo), z1, (0, 1))
    out += dress(f, L, E_WING, [("bal", 7.2, 1.3, 3.0)], step=L / 3 - 0.01, string=6.6)
    for u in (L / 2 - 5.6, L / 2, L / 2 + 5.6):
        out.append(f.poly(arch_pts(u, 0.0, 4.4, 1.9), DARK, 0.06))
    out += balustrade(f, -0.2, L + 0.2, E_WING, 1.1, urns=6.0)
    # flat roof
    out.append(B(min(xi, xo) + 0.4, max(xi, xo) - 0.4, E_WING - 0.1, E_WING + 0.35, zo + 0.4, z1 - 0.4, tint(LEAD_D, 0.02)))
    out.append(B(min(xi, xm) + 0.4, max(xi, xm) - 0.4, E_WING - 0.1, E_WING + 0.35, z0, zo + 0.5, tint(LEAD_D, 0.02)))
    return out


# ── Gardens ──────────────────────────────────────────────────────────────────
def tree(x, z, h, r, y=0.0, k=None):
    c = LEAF[rng.integers(len(LEAF))] if k is None else LEAF[k % len(LEAF)]
    c = tint(c, 0.06)
    hc = h * 0.68
    prof = [(0.0, 0.0), (r * 0.8, 0.1 * hc), (r, 0.38 * hc), (r * 0.88, 0.68 * hc), (r * 0.45, 0.93 * hc), (0.0, hc)]
    crown = lathe(prof, c, 7).S(1.0, 1.0, rng.uniform(0.85, 1.15)).T(x, y + h - hc, z)
    trunk = cyl(0.45 * h / 20, 0.3 * h / 20, h - hc + 0.8, TRUNK, 5, caps=False).T(x, y, z)
    return [crown, trunk]


def hedge_ring(P, y, h, th, c):
    P = ccw(P)
    inner = offset(P, -th)
    if ring_area(inner) <= 0 or abs(ring_area(inner)) > abs(ring_area(P)):
        return [merge([walls(P, y - 0.2, y + h, c), cap(P, y + h, c)])]
    return [merge([walls(P, y - 0.2, y + h, c), walls(inner, y - 0.2, y + h, c, hole=True), cap(P, y + h, c, holes=[inner])])]


def basin(ring, y_floor, rim_h, c_rim=STONE_D, water=0.3, w=0.45):
    P = ccw(ring)
    inner = offset(P, -w)
    return [merge([walls(P, y_floor - 0.3, y_floor + rim_h, c_rim), walls(inner, y_floor - 0.3, y_floor + rim_h, c_rim, hole=True),
                   cap(P, y_floor + rim_h, c_rim, holes=[inner])]),
            cap(inner, y_floor + rim_h - water, WATER)]


def centre(P):
    x0, x1, z0, z1 = bbox(P)
    return (x0 + x1) / 2, (z0 + z1) / 2


def fountain_statue(x, z, ped_h, fig_h, ped_r=0.8, c=MARBLE):
    return [lathe([(ped_r * 1.3, 0.0), (ped_r * 1.3, 0.3), (ped_r, 0.5), (ped_r * 0.8, ped_h - 0.4), (ped_r * 1.1, ped_h - 0.2),
                   (ped_r * 1.1, ped_h), (0.0, ped_h)], STONE, 10).T(x, 0.0, z),
            statue(x, ped_h, z, fig_h, c)]


def hercules_anteo(P):
    """The fountain of Hercules and Antaeus (Isidro González Velázquez, 1827): a round pond, the circular
    pedestal ringed by columns on its island, and the marble group on top."""
    x, z = centre(P)
    out = basin(P, 0.0, 0.7, STONE_D, 0.3, 0.6)
    out += [cyl(5.2, 5.2, 0.9, STONE_D, 24).T(x, 0.0, z), cyl(4.6, 4.6, 0.6, STONE, 24).T(x, 0.9, z),
            cyl(3.0, 3.0, 5.4, tint(STONE, 0.01), 16).T(x, 1.5, z)]
    for k in range(8):
        a = 2 * math.pi * k / 8
        out.append(cyl(0.32, 0.3, 4.6, MARBLE, 8).T(x + 4.0 * math.cos(a), 1.5, z + 4.0 * math.sin(a)))
    out += [cyl(4.5, 4.5, 0.7, STONE, 24).T(x, 6.1, z), cyl(2.2, 1.8, 1.4, STONE, 12).T(x, 6.8, z),
            statue(x - 0.5, 8.2, z, 3.0), statue(x + 0.5, 8.2, z + 0.3, 2.6)]
    return out


def cut(P):
    """Keep the part of the island garden this model covers (x >= -330, z <= 262)."""
    return clip(clip([tuple(p) for p in P], 0, -330.0, False), 1, 262.0, True)


def gardens():
    out = []
    D = DATA
    hed_par = [h["r"] for h in D["hedges"] if h["g"] == "parterre"]
    hed_isla = [cut(h["r"]) for h in D["hedges"] if h["g"] == "isla"]
    fount_rings = list(D["fountains"].values())

    def is_fount(P):
        c = centre(P)
        return any(inside(c[0], c[1], F) and abs(abs(ring_area(P)) - abs(ring_area(F))) < 0.35 * abs(ring_area(F)) for F in fount_rings)

    # ground: sandy walks over the whole garden, lawns and beds on top
    out.append(cap(D["parterre"], 0.03, SAND))
    out.append(cap(D["isla"], 0.03, SAND))
    for k, G in D["gardens"].items():
        if k in ("235634990", "725305119"):
            out.append(cap(G, 0.03, SAND))
            out += hedge_ring(offset(ccw(G), -4.0), 0.03, 0.6, 0.5, BOX)
            out.append(cap(offset(ccw(G), -4.5), 0.06, GRASS))
    for g in D["grass"]:
        c = centre(g["r"])
        if inside(c[0], c[1], D["salon"]):
            continue
        out.append(cap(cut(g["r"]), 0.06, tint(GRASS, 0.04)))
    # the Parterre: beds with box edging, lawn inside
    for P in hed_par:
        if is_fount(P):
            continue
        out += hedge_ring(P, 0.03, 0.55, 0.45, tint(BOX, 0.05))
        inner = offset(ccw(P), -0.45)
        if ring_area(inner) > 0:
            out.append(cap(inner, 0.12, tint(GRASS, 0.05)))
    # the bosquets of the Isla: tall hedges round blocks of plane trees
    for P in hed_isla:
        if is_fount(P):
            continue
        a = abs(ring_area(P))
        out += hedge_ring(P, 0.03, 1.8, 0.7, tint(BOX, 0.05))
        inner = offset(ccw(P), -0.7)
        if ring_area(inner) > 0:
            out.append(cap(inner, 0.08, GRASS_D))
        if a > 60:
            out += trees_in(P, 12.5, (18.0, 27.0), (6.0, 8.0), margin=3.0)
    # the Salón de los Reyes Católicos: rows of plane trees along the Tagus
    S = [p for p in D["salon"]]
    S = clip(S, 0, -330.0, False)
    out.append(cap(S, 0.07, tint(GRASS, 0.03)))
    a, b = np.array([-382.7, 32.0]), np.array([-99.4, -61.1])        # the axis of the Salón
    t = (b - a) / np.linalg.norm(b - a); n = np.array([t[1], -t[0]])
    for off in (-13.0, -4.5, 4.5, 13.0):
        for u in np.arange(6.0, np.linalg.norm(b - a) - 4.0, 9.0):
            p = a + t * u + n * off + rng.normal(0, 0.6, 2)
            if p[0] < -326 or not inside(p[0], p[1], S):
                continue
            out += tree(p[0], p[1], rng.uniform(24, 32), rng.uniform(5.5, 7.0))
    # OSM trees and tree rows
    for x, z, h in D["trees"]:
        out += tree(x, z, h or 14.0, (h or 14.0) * 0.32)
    for tr in D["tree_rows"]:
        P = np.array(tr["p"])
        for k in range(len(P) - 1):
            L = float(np.linalg.norm(P[k + 1] - P[k]))
            for u in np.arange(0, L, 8.0):
                p = P[k] + (P[k + 1] - P[k]) * u / L
                out += tree(p[0], p[1], rng.uniform(18, 24), rng.uniform(4.0, 5.5))
    # fountains
    F = D["fountains"]
    out += hercules_anteo(F["Hercules y Anteo"])
    P = F["Ceres"]; x, z = centre(P)
    out += basin(P, 0.0, 0.7, STONE_D, 0.3, 0.6)
    out += [cyl(2.6, 2.2, 1.2, STONE_D, 12).T(x, 0.0, z)] + fountain_statue(x, z, 3.2, 2.6, 1.3)
    for k in ("Nereida W", "Nereida E"):
        P = F[k]; x, z = centre(P)
        out += basin(P, 0.0, 0.6) + fountain_statue(x, z, 1.8, 2.0, 0.7)
    for k in ("Jardin del Rey", "Jardin de la Reina"):
        P = F[k]; x, z = centre(P)
        out += basin(P, 0.0, 0.5, w=0.3) + [cyl(0.25, 0.15, 1.2, STONE, 8).T(x, 0.0, z)]
    for k, (ph, fh, pr) in {"Hercules e Hidra": (3.6, 2.6, 1.0), "Apolo": (2.6, 2.4, 0.7), "Boticaria": (2.0, 2.0, 0.8),
                            "Horas": (2.4, 1.6, 0.8), "Nino de la Espina": (2.2, 1.4, 0.7), "Venus": (2.4, 2.0, 0.8)}.items():
        P = F[k]; x, z = centre(P)
        out += basin(P, 0.0, 0.6) + fountain_statue(x, z, ph, fh, pr, BRONZE if k == "Nino de la Espina" else MARBLE)
    for w in D["water"]:                                         # the four ponds round the Hydra
        out += basin(w["r"], 0.0, 0.5, w=0.4)
    # the ha-ha moat of the Parterre: stone walls, water below the garden
    for M in D["moats"]:
        P = ccw(M)
        out.append(merge([walls(P, -2.8, 0.25, STONE_D, hole=True), cap(P, -1.6, WATER)]))
        out.append(merge([walls(offset(P, 0.5), -0.1, 0.25, STONE), cap(offset(P, 0.5), 0.25, STONE, holes=[P])]))
    # the bridges over the Ría
    for P in D["bridges"]:
        P = ccw(P)
        out.append(merge([walls(P, -1.2, 0.5, STONE_D), cap(P, 0.5, SAND)]))
        x0, x1, z0, z1 = bbox(P)
        if x1 - x0 > z1 - z0:
            for zz in (z0 + 0.25, z1 - 0.25):
                out.append(B(x0, x1, 0.5, 1.4, zz - 0.25, zz + 0.25, STONE))
        else:
            for xx in (x0 + 0.25, x1 - 0.25):
                out.append(B(xx - 0.25, xx + 0.25, 0.5, 1.4, z0, z1, STONE))
    return out


def trees_in(P, step, hr, rr, margin=2.5):
    x0, x1, z0, z1 = bbox(P)
    inner = offset(ccw(P), -margin)
    out = []
    for x in np.arange(x0 + step / 2, x1, step):
        for z in np.arange(z0 + step / 2, z1, step):
            px, pz = x + rng.normal(0, step * 0.15), z + rng.normal(0, step * 0.15)
            if inside(px, pz, inner):
                out += tree(px, pz, rng.uniform(*hr), rng.uniform(*rr))
    if not out:
        c = centre(P)
        if inside(c[0], c[1], P):
            out += tree(c[0], c[1], rng.uniform(*hr), rng.uniform(*rr) * 0.8)
    return out


