FOOTPRINT = [(-330.0, 262.0), (-228.1, 262.0), (-224.7, 252.0), (-182.2, 194.8), (-138.7, 141.0), (-103.6, 96.0),
             (-103.4, 78.9), (-97.0, -1.1), (-61.6, 12.0), (-60.6, 90.4), (61.9, 90.4), (61.9, 12.0), (57.3, 12.0),
             (57.3, -20.0), (56.2, -21.0), (57.6, -82.0), (57.5, -260.0), (38.2, -261.0), (33.8, -268.0),
             (29.0, -273.5), (23.0, -278.0), (15.0, -281.5), (5.5, -284.0), (-8.0, -282.0), (-15.0, -278.5),
             (-22.0, -273.0), (-28.0, -265.0), (-39.0, -263.0), (-52.0, -71.5), (-58.5, -72.5), (-63.4, -83.3),
             (-81.3, -83.7), (-150.2, -62.2), (-330.0, -11.6)]


def main():
    parts = [("palace", merge(palace())), ("gardens", merge(gardens()))]
    out_dir = ROOT / "models" / "Q530129"
    out_dir.mkdir(parents=True, exist_ok=True)
    named, water = [], []
    for name, m in parts:
        wet = np.all(np.abs(m.c[m.f] - np.array(WATER)).max(axis=2) < 1e-6, axis=1)
        if wet.any():
            water.append(Mesh(m.v, m.f[wet], m.c)); m = Mesh(m.v, m.f[~wet], m.c)
        k = 0.95 + 0.05 * fbm(m.v, 0.06, 7, 2)
        m.c = np.clip(m.c * k[:, None], 0, 1)
        used = np.unique(m.f)
        remap = np.full(len(m.v), -1); remap[used] = np.arange(len(used))
        named.append((name, Mesh(m.v[used], remap[m.f], m.c[used])))
    w = merge(water)
    used = np.unique(w.f)
    remap = np.full(len(w.v), -1); remap[used] = np.arange(len(used))
    named.append(("water", Mesh(w.v[used], remap[w.f], w.c[used]), {"material": "water"}))
    from ground_fill import courtyard_floor
    floor = courtyard_floor([p[1] for p in named], "Q530129")
    if floor is not None:
        named.append(("courtyards", floor))
    tris, size = write_glb(out_dir / "model.glb", named, roughness=0.88,
                           materials={"water": {"metallic": 0.0, "roughness": 0.12}})
    meta = out_dir / "meta.json"
    if meta.exists():
        mj = json.loads(meta.read_text(encoding="utf-8"))
        mj["triangles"] = int(tris)
        mj["footprint"] = [[round(x, 1), round(z, 1)] for x, z in FOOTPRINT]
        meta.write_text(json.dumps(mj, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline=chr(10))
    print(f"{tris} triangles, {size / 1e6:.2f} MB")


if __name__ == "__main__":
    main()
